import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.Dxeykp0S.js";const u=JSON.parse('{"title":"Day 1 · 搭建现代化的 Python 开发环境","description":"","frontmatter":{},"headers":[],"relativePath":"warmup/01-setup.md","filePath":"warmup/01-setup.md","lastUpdated":1787141678000}'),l={name:"warmup/01-setup.md"};function d(i,t,n,h,c,s){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="day-1-·-搭建现代化的-python-开发环境" tabindex="-1">Day 1 · 搭建现代化的 Python 开发环境 <a class="header-anchor" href="#day-1-·-搭建现代化的-python-开发环境" aria-label="Permalink to &quot;Day 1 · 搭建现代化的 Python 开发环境&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>Python 开发需要管理解释器版本、项目依赖与虚拟环境。<a href="https://astral.sh/" target="_blank" rel="noreferrer">Astral</a> 公司出品的 <strong>uv</strong>（用 Rust 编写）把这些工作整合进一个工具，让我们可以一步到位搭好现代化开发环境。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>安装 uv，并理解它如何管理 Python、依赖与项目</li><li>理解虚拟环境（venv）的作用与项目隔离机制</li><li>初始化第一个 <code>pyproject.toml</code> 项目</li><li>配置好编辑器，获得类型提示与代码跳转能力</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://docs.astral.sh/uv/" target="_blank" rel="noreferrer">uv 官方文档</a> —— 重点看 Getting started 和 Projects 两节</li><li><a href="https://docs.python.org/zh-cn/3/tutorial/venv.html" target="_blank" rel="noreferrer">Python 官方：虚拟环境入门</a></li><li><a href="https://peps.python.org/pep-0621/" target="_blank" rel="noreferrer">pyproject.toml 规范（PEP 621）</a></li><li>可选的 Node 生态对照（不影响本课学习）：</li></ul><table tabindex="0"><thead><tr><th>Node 世界</th><th>Python 世界</th></tr></thead><tbody><tr><td>nvm / fnm</td><td>uv python（管理 Python 版本）</td></tr><tr><td>npm / pnpm</td><td>uv（装包、锁版本）</td></tr><tr><td>package.json</td><td>pyproject.toml</td></tr><tr><td>package-lock.json</td><td>uv.lock</td></tr><tr><td>node_modules/</td><td>.venv/</td></tr><tr><td>node index.js</td><td>uv run main.py</td></tr><tr><td>npx xxx</td><td>uvx xxx</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><p>现在我们来检验一下今天的学习情况，完成以下步骤：</p><ol><li>安装 uv：<code>curl -LsSf https://astral.sh/install.sh | sh</code>（macOS 也可以 <code>brew install uv</code>）</li><li>用 <code>uv python install 3.12</code> 安装一个 Python 3.12，用 <code>uv python list</code> 确认</li><li>在任意空目录执行 <code>uv init hello-python</code>，观察它生成了哪些文件</li><li>打开生成的 <code>pyproject.toml</code>，理解 <code>dependencies</code>、<code>requires-python</code> 等字段的含义</li><li>执行 <code>uv add rich</code>，然后观察 <code>pyproject.toml</code> 和 <code>uv.lock</code> 的变化</li><li>修改 <code>main.py</code>，用 rich 打印一个彩色表格，执行 <code>uv run main.py</code></li><li>在 VS Code 中安装 Python 扩展，将解释器指向项目的 <code>.venv</code>，确认类型提示和跳转正常工作</li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><p>今天代码部分其实比较简单，主要是把环境理顺。回顾一下自己是否已经掌握以下概念：</p><ul><li>为什么 Python 强烈建议每个项目使用独立的虚拟环境？</li><li><code>uv run</code> 和直接 <code>python main.py</code> 有什么区别？</li><li><code>uv.lock</code> 应该提交到 Git 吗？为什么？</li><li>如果不小心用了系统 Python 全局 <code>pip install</code>，会发生什么？</li><li><code>uvx ruff check</code> 这行命令做了什么？</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在你的笔记本里记录今天的学习笔记：</p><ul><li>日期，今天的学习总用时，今天学习的目标是什么，是否达成</li><li>哪些东西今天了解得比较透彻，说说自己的理解</li><li>哪些东西今天了解到了一些，还有哪些点需要后续继续深入阅读</li><li>哪些东西今天学了之后还有很多疑问没有被解答，把问题记录下来</li></ul><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://docs.astral.sh/ruff/" target="_blank" rel="noreferrer">Ruff</a> —— 同一个团队出品的 linter/formatter，对标 ESLint + Prettier，快到离谱</li><li><a href="https://chriswarrick.com/blog/2023/01/15/how-to-improve-python-packaging/" target="_blank" rel="noreferrer">Python 包管理工具简史</a> —— 了解历史，才知道 uv 解决了什么</li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节我们进入 <a href="./02-python-vs-js">Python 核心思维课</a>，通过实验理解 Python 的关键语义。</p>',21)])])}const y=e(l,[["render",d]]);export{u as __pageData,y as default};
